// standardViewsUsage displays the usage of the standard-views command and its
// subcommands.
func standardViewsUsage() {
	fmt.Fprintln(os.Stderr, "Service is the standard_views service interface.")
	fmt.Fprintf(os.Stderr, "Usage:\n    %s [globalflags] standard-views COMMAND [flags]\n\n", os.Args[0])
	fmt.Fprintln(os.Stderr, "COMMAND:")
	fmt.Fprintln(os.Stderr, "    list-project: ListProject implements list_project.")
	fmt.Fprintln(os.Stderr, "    create-project: CreateProject implements create_project.")
	fmt.Fprintln(os.Stderr, "    retrieve-project: RetrieveProject implements retrieve_project.")
	fmt.Fprintln(os.Stderr, "    update-project: UpdateProject implements update_project.")
	fmt.Fprintln(os.Stderr, "    patch-project: PatchProject implements patch_project.")
	fmt.Fprintln(os.Stderr, "    delete-project: DeleteProject implements delete_project.")
	fmt.Fprintln(os.Stderr, "    list-workspace: ListWorkspace implements list_workspace.")
	fmt.Fprintln(os.Stderr, "    create-workspace: CreateWorkspace implements create_workspace.")
	fmt.Fprintln(os.Stderr, "    retrieve-workspace: RetrieveWorkspace implements retrieve_workspace.")
	fmt.Fprintln(os.Stderr, "    update-workspace: UpdateWorkspace implements update_workspace.")
	fmt.Fprintln(os.Stderr, "    patch-workspace: PatchWorkspace implements patch_workspace.")
	fmt.Fprintln(os.Stderr, "    delete-workspace: DeleteWorkspace implements delete_workspace.")
	fmt.Fprintln(os.Stderr)
	fmt.Fprintln(os.Stderr, "Additional help:")
	fmt.Fprintf(os.Stderr, "    %s standard-views COMMAND --help\n", os.Args[0])
}
